# @option --size <size>                         The size (in bits) of the key for RSA and oct key types
# @option --comment <value>                     The comment used when adding the certificate to an agent
# @option --kms <uri>                           The uri to configure a (cloud) KMS or an HSM
# @option --x5c-cert <chain>                    Certificate (chain) in PEM format to store in the 'x5c' header of a JWT
# @option --x5c-key <file>                      Private key file, used to sign a JWT, corresponding to the certificate that will be stored in the 'x5c' header
# @option --x5c-chain <file>                    Certificate file, in PEM format
# @option --nebula-cert <file>                  Certificate file in PEM format to store in the 'nebula' header of a JWT
